"""A minimal, dependency-free client for OpenAI's Responses API.

Set ``OPENAI_API_KEY`` in the environment, then use ``create_response`` or:

    python openai_client.py --model MODEL "Your prompt"

This module does not log prompts or responses. Requests set ``store`` to false
by default so that API-side storage is not requested.
"""

from __future__ import annotations

import argparse
import json
import os
import sys
from typing import Any, Mapping
from urllib.error import HTTPError, URLError
from urllib.request import Request, urlopen


RESPONSES_URL = "https://api.openai.com/v1/responses"
DEFAULT_TIMEOUT = 60.0


class OpenAIError(RuntimeError):
    """An error returned while communicating with the OpenAI API."""


def create_response(
    prompt: str,
    *,
    model: str,
    api_key: str | None = None,
    instructions: str | None = None,
    max_output_tokens: int | None = None,
    timeout: float = DEFAULT_TIMEOUT,
    store: bool = False,
) -> dict[str, Any]:
    """Send *prompt* to the Responses API and return its decoded JSON object.

    ``api_key`` defaults to ``OPENAI_API_KEY``.  The prompt is sent only in
    the HTTPS request and is never written to disk or included in exceptions.
    Pass ``store=True`` only if API-side response storage is desired.
    """
    if not isinstance(prompt, str) or not prompt:
        raise ValueError("prompt must be a non-empty string")
    if not isinstance(model, str) or not model:
        raise ValueError("model must be a non-empty string")
    if timeout <= 0:
        raise ValueError("timeout must be positive")
    if max_output_tokens is not None and max_output_tokens <= 0:
        raise ValueError("max_output_tokens must be positive")

    key = api_key or os.environ.get("OPENAI_API_KEY")
    if not key:
        raise OpenAIError("Set OPENAI_API_KEY or pass api_key explicitly.")

    payload: dict[str, Any] = {"model": model, "input": prompt, "store": store}
    if instructions is not None:
        payload["instructions"] = instructions
    if max_output_tokens is not None:
        payload["max_output_tokens"] = max_output_tokens

    request = Request(
        RESPONSES_URL,
        data=json.dumps(payload).encode("utf-8"),
        headers={
            "Authorization": f"Bearer {key}",
            "Content-Type": "application/json",
            "Accept": "application/json",
        },
        method="POST",
    )
    try:
        with urlopen(request, timeout=timeout) as response:
            body = response.read()
    except HTTPError as error:
        # Do not expose the response body: an intermediary could echo prompt text.
        raise OpenAIError(f"OpenAI API request failed with HTTP {error.code}.") from None
    except URLError as error:
        raise OpenAIError("Could not connect to the OpenAI API.") from error
    except OSError as error:
        raise OpenAIError("Network error while contacting the OpenAI API.") from error

    try:
        result = json.loads(body.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError) as error:
        raise OpenAIError("OpenAI API returned an invalid JSON response.") from error
    if not isinstance(result, dict):
        raise OpenAIError("OpenAI API returned an unexpected response format.")
    return result


def output_text(response: Mapping[str, Any]) -> str:
    """Return concatenated text from a Responses API response.

    Non-text output, such as tool calls or refusals, is intentionally omitted.
    """
    parts: list[str] = []
    for item in response.get("output", []):
        if not isinstance(item, Mapping) or item.get("type") != "message":
            continue
        for content in item.get("content", []):
            if isinstance(content, Mapping) and content.get("type") == "output_text":
                text = content.get("text")
                if isinstance(text, str):
                    parts.append(text)
    return "".join(parts)


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description="Send a private prompt to OpenAI.")
    parser.add_argument("prompt", help="Text prompt to send")
    parser.add_argument("--model", required=True, help="OpenAI model ID")
    parser.add_argument("--instructions", help="Optional system-level instructions")
    parser.add_argument("--max-output-tokens", type=int)
    parser.add_argument("--timeout", type=float, default=DEFAULT_TIMEOUT)
    parser.add_argument(
        "--json", action="store_true", help="Print the complete API response JSON"
    )
    args = parser.parse_args(argv)

    try:
        response = create_response(
            args.prompt,
            model=args.model,
            instructions=args.instructions,
            max_output_tokens=args.max_output_tokens,
            timeout=args.timeout,
        )
    except (OpenAIError, ValueError) as error:
        print(f"Error: {error}", file=sys.stderr)
        return 1

    if args.json:
        print(json.dumps(response, ensure_ascii=False, indent=2))
    else:
        print(output_text(response))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
